content.content:
// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
// and future backends). One C++20 binary that selects a model (fast / cycle
// / hybrid), resolves engines at runtime, and either passes through to a single
// engine or orchestrates a hybrid round-trip.
//
// This file owns argument dispatch only: parse the CLI, route to a command.
#include <cstdio>
#include <cstdlib>
#include <exception>
#include <string>
#include <string_view>

#include "cli.hpp"
#include "dev_mode.hpp"
#include "log.hpp"

namespace andes_sim {
int cmd_list(const Cli& cli);
int cmd_doctor(const Cli& cli);
int cmd_run(const Cli& cli);
int cmd_profile(const Cli& cli);
int cmd_version();
}  // namespace andes_sim

namespace {

using andes_sim::Cli;
using andes_sim::cmd_doctor;
using andes_sim::cmd_list;
using andes_sim::cmd_profile;
using andes_sim::cmd_run;
using andes_sim::cmd_version;
using andes_sim::is_dev_mode;

// The known command names live in cli.cpp (is_subcommand): the parser needs
// them for the default-command rule, so parse_cli only ever yields run/
// profile/list/doctor (or "" for no args / top-level help). Developer
// build/test tooling lives in scripts/, not the binary.

// ---- help model: the user-facing surface rendered as a command tree --------
//
// `run`'s two subcommand groups -- the modes (the composition axis) ...
struct ModeRow {
  const char* name;
  const char* brief;
};
constexpr ModeRow kRunModes[] = {
    {"fast", "QEMU only -- functional, full speed"},
    {"cycle", "one cycle-accurate engine, from reset"},
    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
};

// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
struct TargetRow {
  const char* name;
  const char* brief;
  bool dev;
};
constexpr TargetRow kListTargets[] = {
    {"models", "the modes and their engines", false},
    {"engines", "discovered cycle-accurate engines", false},
    {"fixtures", "internal test ELFs (developer target)", true},
};

// ... and `run`'s options. Each `flag` carries its own leading indent (the pc
// boundaries nest under --trigger pc). `tag` marks a required option (and WHEN
// it is required).
struct OptRow {
  const char* flag;  // includes its own leading indent
  const char* tag;
  const char* brief;
};
constexpr OptRow kRunOpts[] = {
    {"  --mode fast|cycle|hybrid", "REQUIRED", "which mode to run"},
    {"  --trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter"},
    {"    --pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary"},
    {"    --pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary"},
    {"  --engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)"},
    {"  --mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)"},
    {"  --dry-run", "", "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)"},
    {"  --print-memmap", "", "print the hybrid guest memory map and exit, running nothing (hybrid only; ELF optional)"},
    {"  --verify", "", "cross-check the hybrid run against a QEMU oracle"},
    {"  --kanata <file>", "", "write a Kanata pipeline trace of the ROI (hybrid only; open in Konata)"},
    {"    --objdump <file>", "", "embed that objdump -d dump's disassembly in the trace (requires --kanata)"},
    {"  --gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)"},
    {"  --gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)"},
    {"  --log-level <0-6>", "", "verbosity, vsim's scale: 0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off (default 2: program output + the cycle figure)"},
    {"  --log-file <file>", "", "append EVERY level's messages (timestamped) to <file>; the console keeps --log-level"},
    {"  --step-timeout-ms <ms>", "", "hybrid per-leg spawn timeout (default 90000); raise it for a large ROI on the cycle-accurate leg"},
    {"  -- <args...>", "", "forward everything after -- verbatim to the engine (fast/cycle); hybrid rejects -- args, EXCEPT --runtime linux, where they are app argv"},
};

// A major command line at column 0: `name   brief`.
void print_major(std::FILE* out, const char* name, const char* brief) {
  std::fprintf(out, "%-7s %s\n", name, brief);
}

// A subcommand/target line, indented two under its command: `  name   brief`.
void print_sub(std::FILE* out, const char* name, const char* brief) {
  std::fprintf(out, "  %-9s %s\n", name, brief);
}

// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
void print_opt(std::FILE* out, const OptRow& o) {
  if (o.tag[0])
    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
  else
    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
}

// `run`: major line, the mode subcommands, then the option list. Shared by
// the top-level tree and `run --help`.
void print_run_block(std::FILE* out) {
  print_major(out, "run", "run one simulation (the default: 'run' may be omitted)");
  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
  std::fputs("\n", out);
  for (const OptRow& o : kRunOpts) print_opt(out, o);
}

void print_list_block(std::FILE* out) {
  print_major(out, "list", "list what is available");
  for (const TargetRow& t : kListTargets) {
    if (t.dev && !is_dev_mode()) continue;
    print_sub(out, t.name, t.brief);
  }
}

// ... and `profile`'s options (the report knobs; the QEMU shape -- binary,
// -cpu, -readconfig -- comes from the engine, not from flags).
constexpr OptRow kProfileOpts[] = {
    {"  --engine <id>", "", "the engine whose QEMU config to profile on (default: the sole one)"},
    {"  --limit <N>", "", "report the top-N loops (default 50)"},
    {"  --min-iters <N>", "", "drop loops with fewer iterations (default 1)"},
    {"  --no-optimize-rvv", "", "keep scalar loops too (default: RVV-only)"},
    {"  --no-llm", "", "plain table instead of the LLM Markdown report"},
    {"  --no-source", "", "skip source file:line resolution (addr2line)"},
    {"  --objdump <bin>", "", "override the disassembler (default: $HYBRID_TOOLCHAIN's)"},
    {"  --addr2line <bin>", "", "override the source resolver"},
    {"  --raw", "", "dump the raw plugin log, no report"},
    {"  --mem-size <spec>", "", "guest RAM, forwarded as QEMU -m"},
    {"  --dry-run", "", "print the exact QEMU command and exit, running nothing"},
    {"  -- <args...>", "", "forward everything after -- verbatim to QEMU"},
};

void print_profile_block(std::FILE* out) {
  print_major(out, "profile",
              "find hot loops under QEMU, configured like the engine "
              "(reports --pc-start/--pc-end windows for hybrid)");
  std::fputs("\n", out);
  for (const OptRow& o : kProfileOpts) print_opt(out, o);
}

void print_doctor_block(std::FILE* out) {
  print_major(out, "doctor", "check toolchain + fixtures are present");
}

// Top-level `andesim --help`: the whole tree -- every major command, its
// subcommands, and run's full option list, so one screen shows everything.
void print_usage(std::FILE* out) {
  std::fputs("usage: andesim [command] [options] <ELF> [-- <engine args>]\n\n",
             out);
  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n",
             out);
  std::fputs("64-bit RISC-V only: 32-bit workloads and engines are not "
             "supported.\n\n",
             out);
  print_run_block(out);
  std::fputs("\n", out);
  print_profile_block(out);
  std::fputs("\n", out);
  print_list_block(out);
  std::fputs("\n", out);
  print_doctor_block(out);
  std::fputs(
      "\n--version  the identity of every bundled component "
      "(andesim, the shared ABI, qemu, the engine)\n",
      out);
  std::fputs(
      "\n'andesim run --help' / 'andesim profile --help' / 'andesim list "
      "--help' for per-command detail.\n",
      out);
}

// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
// parse_cli admits only run/list/doctor/profile, so `run` is the fallthrough.
void print_subcommand_help(std::string_view name, std::FILE* out) {
  if (name == "list") { print_list_block(out); return; }
  if (name == "doctor") { print_doctor_block(out); return; }
  if (name == "profile") { print_profile_block(out); return; }
  print_run_block(out);
}

}  // namespace

int main(int argc, char** argv) {
  using namespace andes_sim;

  Cli cli = parse_cli(argc, argv);
  if (!cli.error.empty()) {
    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
    return 2;
  }

  if (cli.version) return cmd_version();

  if (!set_log_threshold(cli.log_level)) {
    std::fprintf(stderr,
                 "andesim: invalid --log-level '%s' (0=trace 1=debug 2=info "
                 "3=warn 4=error 5=critical 6=off)\n",
                 cli.log_level.c_str());
    return 2;
  }
  if (!set_log_file(cli.log_file)) {
    std::fprintf(stderr, "andesim: cannot open --log-file '%s' for append\n",
                 cli.log_file.c_str());
    return 2;
  }

  if (cli.subcommand.empty()) {  // no command, or top-level -h
    if (cli.help) {
      print_usage(stdout);
      return 0;
    }
    print_usage(stderr);
    return 2;
  }

  if (cli.help) {
    print_subcommand_help(cli.subcommand, stdout);
    return 0;
  }

  if (cli.subcommand == "list") return cmd_list(cli);
  if (cli.subcommand == "doctor") return cmd_doctor(cli);
  if (cli.subcommand == "profile") return cmd_profile(cli);
  return cmd_run(cli);  // parse_cli admits only run/list/doctor/profile
}

